from twlab.evaluation import WeeklyObservation, block_bootstrap_mean, ObservationError

def test_degenerate_bootstrap_is_not_reported_as_confidence():
    rows = [WeeklyObservation(f'2024-W{w:02}', str(w), 'historical_numeric_temporally_controlled', None, True, v) for w, v in zip([1,3,5,7], [.1,-.1,.3,.5])]
    try:
        r = block_bootstrap_mean(rows, block_length=1, n_boot=1000, seed=1)
    except ObservationError:
        return
    assert r.ci_low < r.ci_high

# Rechazar o señalar explícitamente que el diseño no permite estimar incertidumbre; no cambiar silenciosamente el bloque.
